begin;
create extension if not exists pgcrypto;
create type public.store_status as enum ('draft','active','suspended');
create type public.product_status as enum ('draft','published','archived','suspended');
create type public.order_status as enum ('pending','paid','partially_refunded','refunded','failed');
create type public.entitlement_status as enum ('active','revoked');

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table public.stores(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),name text not null check(char_length(name) between 2 and 80),slug text not null unique check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),status public.store_status not null default 'draft',created_at timestamptz not null default now());
create table public.stripe_accounts(store_id uuid primary key references public.stores(id) on delete cascade,account_id text not null unique check(account_id~'^acct_'),onboarding_status text not null default 'pending' check(onboarding_status in('pending','restricted','complete')),details_submitted boolean not null default false,charges_enabled boolean not null default false,payouts_enabled boolean not null default false,updated_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),title text not null check(char_length(title) between 2 and 160),slug text not null check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),description text,price_minor integer not null check(price_minor>0),currency text not null check(currency in('eur','usd','gbp')),status public.product_status not null default 'draft',created_at timestamptz not null default now(),unique(store_id,slug));
create table public.product_files(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,storage_path text not null unique,filename text not null,mime_type text not null check(mime_type in('application/pdf','application/zip','application/x-zip-compressed')),size_bytes bigint not null check(size_bytes between 1 and 104857600),created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references public.profiles(id),store_id uuid not null references public.stores(id),status public.order_status not null default 'pending',currency text not null check(currency in('eur','usd','gbp')),total_minor integer not null check(total_minor>0),platform_fee_minor integer not null check(platform_fee_minor>=0 and platform_fee_minor<=total_minor),stripe_checkout_session_id text unique,stripe_payment_intent_id text unique,stripe_connected_account_id text,paid_at timestamptz,created_at timestamptz not null default now());
create index orders_buyer_created_idx on public.orders(buyer_id,created_at desc);create index orders_store_created_idx on public.orders(store_id,created_at desc);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),product_id uuid not null references public.products(id),unit_price_minor integer not null check(unit_price_minor>0),quantity integer not null check(quantity>0),product_snapshot jsonb not null,unique(order_id,product_id));
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders(id),provider text not null check(provider='stripe'),provider_payment_id text not null unique,connected_account_id text not null,status text not null check(status in('succeeded','refunded','partially_refunded')),amount_minor integer not null check(amount_minor>0),currency text not null,created_at timestamptz not null default now());
create table public.entitlements(id uuid primary key default gen_random_uuid(),order_item_id uuid not null unique references public.order_items(id),buyer_id uuid not null references public.profiles(id),product_id uuid not null references public.products(id),status public.entitlement_status not null default 'active',created_at timestamptz not null default now());create index entitlements_buyer_idx on public.entitlements(buyer_id,status);
create table public.refunds(id uuid primary key default gen_random_uuid(),payment_id uuid not null references public.payments(id),provider_refund_reference text,amount_minor integer not null check(amount_minor>0),status text not null check(status in('pending','partial','succeeded','failed')),created_at timestamptz not null default now());
create table public.webhook_events(provider text not null,event_id text not null,event_type text not null,connected_account_id text,status text not null default 'processing' check(status in('processing','processed','failed')),error_message text,received_at timestamptz not null default now(),processed_at timestamptz,primary key(provider,event_id));
create table public.download_events(id bigint generated always as identity primary key,entitlement_id uuid not null references public.entitlements(id),buyer_id uuid not null references public.profiles(id),product_file_id uuid not null references public.product_files(id),created_at timestamptz not null default now());

alter table public.profiles enable row level security;alter table public.stores enable row level security;alter table public.stripe_accounts enable row level security;alter table public.products enable row level security;alter table public.product_files enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.payments enable row level security;alter table public.entitlements enable row level security;alter table public.refunds enable row level security;alter table public.webhook_events enable row level security;alter table public.download_events enable row level security;
grant select on public.stores,public.products to anon,authenticated;grant select,insert,update on public.profiles,public.stores,public.products,public.product_files to authenticated;grant select on public.stripe_accounts,public.orders,public.order_items,public.payments,public.entitlements,public.refunds to authenticated;revoke all on public.webhook_events,public.download_events from anon,authenticated;

create policy "public active stores" on public.stores for select to anon,authenticated using(status='active' or owner_id=(select auth.uid()));
create policy "owners create stores" on public.stores for insert to authenticated with check(owner_id=(select auth.uid()));create policy "owners update stores" on public.stores for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy "users read profiles" on public.profiles for select to authenticated using(id=(select auth.uid()));create policy "users update profiles" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "published products" on public.products for select to anon,authenticated using(status='published' or exists(select 1 from public.stores s where s.id=store_id and s.owner_id=(select auth.uid())));create policy "owners insert products" on public.products for insert to authenticated with check(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=(select auth.uid())));create policy "owners update products" on public.products for update to authenticated using(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=(select auth.uid()))) with check(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=(select auth.uid())));
create policy "owners read stripe" on public.stripe_accounts for select to authenticated using(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=(select auth.uid())));create policy "owners read files" on public.product_files for select to authenticated using(exists(select 1 from public.products p join public.stores s on s.id=p.store_id where p.id=product_id and s.owner_id=(select auth.uid())));create policy "owners insert files" on public.product_files for insert to authenticated with check(exists(select 1 from public.products p join public.stores s on s.id=p.store_id where p.id=product_id and s.owner_id=(select auth.uid())));
create policy "buyers owners read orders" on public.orders for select to authenticated using(buyer_id=(select auth.uid()) or exists(select 1 from public.stores s where s.id=store_id and s.owner_id=(select auth.uid())));create policy "buyers owners read items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o join public.stores s on s.id=o.store_id where o.id=order_id and(o.buyer_id=(select auth.uid()) or s.owner_id=(select auth.uid()))));create policy "buyers owners read payments" on public.payments for select to authenticated using(exists(select 1 from public.orders o join public.stores s on s.id=o.store_id where o.id=order_id and(o.buyer_id=(select auth.uid()) or s.owner_id=(select auth.uid()))));create policy "buyers read entitlements" on public.entitlements for select to authenticated using(buyer_id=(select auth.uid()));create policy "buyers owners read refunds" on public.refunds for select to authenticated using(exists(select 1 from public.payments p join public.orders o on o.id=p.order_id join public.stores s on s.id=o.store_id where p.id=payment_id and(o.buyer_id=(select auth.uid()) or s.owner_id=(select auth.uid()))));

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-files','product-files',false,104857600,array['application/pdf','application/zip','application/x-zip-compressed']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "creator storage uploads" on storage.objects for insert to authenticated with check(bucket_id='product-files' and exists(select 1 from public.stores s where s.id::text=(storage.foldername(name))[1] and s.owner_id=(select auth.uid())));create policy "creator storage reads" on storage.objects for select to authenticated using(bucket_id='product-files' and exists(select 1 from public.stores s where s.id::text=(storage.foldername(name))[1] and s.owner_id=(select auth.uid())));

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))) on conflict do nothing;return new;end$$;revoke all on function public.handle_new_user() from public,anon,authenticated;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.claim_webhook_event(p_provider text,p_event_id text,p_event_type text,p_connected_account_id text) returns boolean language plpgsql security definer set search_path='' as $$begin insert into public.webhook_events(provider,event_id,event_type,connected_account_id) values(p_provider,p_event_id,p_event_type,p_connected_account_id) on conflict do nothing;return found;end$$;revoke all on function public.claim_webhook_event(text,text,text,text) from public,anon,authenticated;grant execute on function public.claim_webhook_event(text,text,text,text) to service_role;
create or replace function public.fulfill_paid_order(p_order_id uuid,p_checkout_session_id text,p_payment_intent_id text,p_connected_account_id text,p_amount_minor integer,p_currency text) returns void language plpgsql security definer set search_path='' as $$declare v_order public.orders%rowtype;begin select * into v_order from public.orders where id=p_order_id for update;if not found then raise exception 'Order not found';end if;if v_order.status='paid' then return;end if;if v_order.status<>'pending' or v_order.total_minor<>p_amount_minor or v_order.currency<>p_currency then raise exception 'Order mismatch';end if;update public.orders set status='paid',stripe_checkout_session_id=p_checkout_session_id,stripe_payment_intent_id=p_payment_intent_id,stripe_connected_account_id=p_connected_account_id,paid_at=now() where id=p_order_id;insert into public.payments(order_id,provider,provider_payment_id,connected_account_id,status,amount_minor,currency) values(p_order_id,'stripe',p_payment_intent_id,p_connected_account_id,'succeeded',p_amount_minor,p_currency) on conflict(order_id) do nothing;insert into public.entitlements(order_item_id,buyer_id,product_id) select oi.id,v_order.buyer_id,oi.product_id from public.order_items oi where oi.order_id=p_order_id on conflict(order_item_id) do nothing;end$$;revoke all on function public.fulfill_paid_order(uuid,text,text,text,integer,text) from public,anon,authenticated;grant execute on function public.fulfill_paid_order(uuid,text,text,text,integer,text) to service_role;
create or replace function public.record_refund(p_charge_id text,p_payment_intent_id text,p_amount_refunded_minor integer,p_status text) returns void language plpgsql security definer set search_path='' as $$declare v_payment public.payments%rowtype;v_order public.orders%rowtype;begin select * into v_payment from public.payments where provider_payment_id=p_payment_intent_id for update;if not found then return;end if;select * into v_order from public.orders where id=v_payment.order_id for update;insert into public.refunds(payment_id,provider_refund_reference,amount_minor,status) values(v_payment.id,p_charge_id,p_amount_refunded_minor,p_status);if p_amount_refunded_minor>=v_order.total_minor then update public.orders set status='refunded' where id=v_order.id;update public.payments set status='refunded' where id=v_payment.id;update public.entitlements set status='revoked' where order_item_id in(select id from public.order_items where order_id=v_order.id);else update public.orders set status='partially_refunded' where id=v_order.id;update public.payments set status='partially_refunded' where id=v_payment.id;end if;end$$;revoke all on function public.record_refund(text,text,integer,text) from public,anon,authenticated;grant execute on function public.record_refund(text,text,integer,text) to service_role;
commit;
